//! Файл: settings/catalog/write_path.rs
//! Что делает: настройки задачи t158 — путь сделки без ожиданий: очередь уведомлений (решение 340), очередь и пачки
//! записи журнала (решение 341), долговечность записи учёта ядра в своём файле (решение 353), отметки ядра и остановка
//! (решения 355, 356). Отдельный файл: base.rs —
//! общий для многих задач. Все необязательные, значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, разделы «Уведомления» и «Система»).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 340, 341, 353, 355, 356. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static WRITE_PATH: &[SettingDef] = &[
    d("Уведомления", "notify.queue_max", K::Integer, L::Positive, "сообщений", G, "Решение 340 (Тигран 16.11: уведомление не имеет права задерживать сделку): уведомления Telegram всегда уходят фоновой очередью — шаг сделки не ждёт отправки; порядок уведомлений сохраняется (одна очередь, по порядку постановки). Это — предел очереди: сколько уведомлений может ждать отправки; больше — новое не ставится, потеря считается и пишется в «Журнал» (notify.queue_lost на 1-й, 2-й, 4-й… потере). Не задана — очередь без предела (ничего не теряется; при долгом сбое Telegram сообщения копятся в памяти и уходят с опозданием)").optional(),
    d("Система", "journal.queue_max", K::Integer, L::Positive, "записей", G, "Решение 341 (по решению владельца 16.11 — очередь журнала работает всегда): запись «Журнала» не ждётся — уходит в очередь, отдельный поток пишет накопленное пачками по порядку; шаги сделок, расчёт кандидатов и пачка пулов DEX не ждут основную базу; чтение «Журнала» дожидается записанного. Это — только предел длины очереди: больше — запись теряется со счётом (запись journal.queue_lost). Не задана — без предела (ничего не теряется; при долгом сбое базы записи копятся в памяти)").optional(),
    d("Система", "journal.batch_max", K::Integer, L::Positive, "записей", G, "Решение 341: не больше стольких записей журнала в одной транзакции пачки. Пачка держит замок основной базы (окна, эпизоды, отчёты, настройки ждут её конца): меньше пачка — короче ожидание у них, но больше транзакций. Учёт сделок от пачек не зависит — он в своём файле (решение 353). Не задана — пачка = всё накопленное к моменту записи").optional(),
    d("Система", "settings.mark_retry_ms", K::Integer, L::Positive, "мс", G, "Решение 355 (ревью t158): запрещающая отметка ядра (монета в чёрном списке по проскальзыванию продажи или недостаче зачисления, закрытие по разрыву выхода, входы с биржи закрыты после отказа вывода) действует сразу — в памяти настроек, а в базу пишется своей задачей. Запись не удалась — запись журнала settings.mark_unsaved (Error) и повтор через столько мс, пока не запишется (или пока значение не изменят). Не задана — без повтора: отметка действует до перезапуска, в журнале «внесите вручную»").optional(),
    d("Уведомления", "notify.stop_wait_ms", K::Integer, L::Positive, "мс", G, "Решение 356 (ревью t158 Б2): остановка бота (Ctrl+C / SIGTERM) — сколько ждать отправки уведомлений, стоящих в очереди, перед выходом (журнал дописывается всегда, до границы на момент сигнала). Не задана — не ждать: стоящие уведомления не уходят (их запись — в журнале как потеря)").optional(),
    d("Уведомления", "notify.info_max_age_s", K::Integer, L::Positive, "секунды", G, "Решение 356 (ревью t158 Н1): уведомление обычной очереди (не алерт риска и не ручное управление — у них своя очередь, вперёд), которое ждало отправки дольше стольких секунд, не отправляется — потеря считается и пишется в «Журнал» (notify.queue_lost). Нужна при долгом сбое Telegram, чтобы хвост старых сообщений не шёл после восстановления. Не задана — отправляются все, сколько бы ни ждали").optional(),
    d("Система", "ledger.synchronous", K::Choice, L::None, "режим SQLite", G, "Решение 353: PRAGMA synchronous писателя файла учёта ядра ledger.sqlite (сделки и их шаги, переводы, итог дня, очередь кошелька DEX); https://www.sqlite.org/pragma.html#pragma_synchronous. FULL — коммит переживает и падение бота, и потерю питания или падение ОС. NORMAL (режим WAL) — коммит переживает падение бота, но последние коммиты могут пропасть при потере питания или падении ОС (после запуска сделка окажется на предыдущем записанном шаге и будет «прервана перезапуском» — проверка вручную); выигрыш — нет синхронизации диска на каждом коммите. EXTRA — надёжнее FULL. OFF не предлагается: учёт денег. Не задана — значение SQLite по умолчанию (у сборки бота — FULL, как у основной базы)").choices(&["NORMAL", "FULL", "EXTRA"]).optional(),
];
